out={}
for vid,s in src.items():
    ph,no,q,an,ex=D[vid]
    assert len(ph)==len(s['phrases']) and len(no)==len(s['nouns']),vid
    pt=[p['text'] for p in s['phrases']]; rec=[]; used=0
    for r in s['recall']:
        if r in pt: rec.append(ph[pt.index(r)])
        elif r in s['nouns']: rec.append(no[s['nouns'].index(r)])
        else: rec.append(ex); used+=1
    assert used==1,(vid,used)
    out[vid]={"phrases":ph,"nouns":no,"question":q,"answer":an,"captions":{},"recall":rec}
assert set(D)==set(src)
json.dump(out,open(f'{H}/tr/b002/es/hu.json','w'),ensure_ascii=False,indent=1)
